# -*- coding: utf-8 -*-
# N2 内容理解(中文) tambahan · 3問 / 各
P1 = "Cari kalimat pendapat penulis (biasanya setelah しかし/だが/つまり) lalu cocokkan dengan parafrasenya."
P2 = "Soal alasan/指示語: baca kalimat sebelum dan sesudah bagian bergaris bawah; jawabannya hampir selalu di sana."
P3 = "Pilihan yang terlalu ekstrem (すべて・必ず・全く) atau memuat hal yang tak ada di teks hampir pasti salah."
JN = 'Teks menengah (内容理解・中文)'
R = ['Tidak disebut dalam teks.', 'Berlawanan dengan isi teks.', 'Berlebihan / bukan pendapat penulis.']
def C(jp, id, qs):
    return dict(slot='chu', jenis=JN, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, [P2, P3, P1][i % 3]) for i, (q, ok, w, al, bu) in enumerate(qs)])
B = [
 C('私の勤める会社では、去年から「在宅勤務」が週に二日認められるようになった。最初は、家で仕事をすれば通勤の疲れもなくなり、効率が上がるだろうと期待していた。\n　ところが、実際に始めてみると、思わぬ問題があった。家では、仕事とそれ以外の境目がなくなり、気がつくと夜遅くまでパソコンに向かっていることが増えたのだ。また、同僚と気軽に相談できないため、ちょっとした疑問を解決するのにも時間がかかった。\n　そこで私は、仕事を始める時間と終わる時間を決め、毎朝、着替えてから机に向かうことにした。また、分からないことは、すぐにチャットで質問するようにした。こうした工夫を続けるうちに、在宅勤務の良さを、ようやく実感できるようになった。',
   'Di perusahaan tempat saya bekerja, sejak tahun lalu bekerja dari rumah diizinkan dua hari seminggu. Awalnya saya berharap, bila bekerja di rumah, lelah perjalanan hilang dan efisiensi naik.\n Namun setelah benar-benar dimulai ada masalah tak terduga. Di rumah batas antara kerja dan lainnya hilang, dan tanpa sadar makin sering menghadap komputer sampai larut. Karena tak bisa berkonsultasi ringan dengan rekan, menyelesaikan pertanyaan kecil pun memakan waktu.\n Maka saya menetapkan jam mulai dan selesai kerja, dan tiap pagi berganti pakaian sebelum duduk di meja. Saya juga langsung bertanya lewat obrolan bila tak paham. Setelah terus melakukan upaya itu, akhirnya saya bisa merasakan kebaikan kerja dari rumah.',
   [('筆者が 在宅勤務を 始めて 困った ことと して 正しい ものは どれか。', '仕事と それ以外の 境目が なくなり、夜遅くまで 働く ことが 増えた', ['通勤で 疲れる ことが 増えた', '会社の パソコンが 使えなかった', '同僚と 毎日 会わなければ ならなかった'], 'Masalah: batas hilang, kerja sampai malam.', '仕事とそれ以外の境目がなくなり'),
    ('筆者が 工夫と して 行って いない ことは どれか。', '仕事の 量を 減らして もらう', ['始める 時間と 終わる 時間を 決める', '毎朝 着替えてから 机に 向かう', '分からない ことを すぐ チャットで 聞く'], 'Mengurangi pekerjaan tidak disebut.', '時間を決め、着替えてから…チャットで質問'),
    ('この 文章の 内容に 合うのは どれか。', '工夫を 重ねた 結果、在宅勤務の 良さを 感じられるように なった', ['在宅勤務は 最初から 問題が なかった', '在宅勤務は 続ける べきでは ないと 考えて いる', '在宅勤務を すると 同僚と 相談する 必要が なくなる'], 'Kesimpulan penulis.', '在宅勤務の良さを、ようやく実感できるようになった')]),
 C('日本には「謙遜」という文化がある。人から褒められたとき、「いえいえ、とんでもないです」と否定するのが礼儀とされてきた。\n　しかし、最近は、この習慣が見直され始めている。自分の長所を認めないことが、かえって褒めてくれた相手に失礼になる場合もあるからだ。また、若い世代の中には、褒められたら素直に「ありがとうございます」と答えるほうが、気持ちよく会話が続くと考える人が増えている。\n　とはいえ、謙遜が持つ「相手を立てる」という本来の意味まで失う必要はない。大切なのは、状況に応じて、相手に対する敬意が伝わる返事を選ぶことだろう。',
   'Di Jepang ada budaya "kerendahan hati". Saat dipuji, menyangkal dengan "ah tidak, mana mungkin" dianggap sopan.\n Namun belakangan kebiasaan ini mulai ditinjau ulang. Sebab tidak mengakui kelebihan sendiri kadang malah tidak sopan pada orang yang memuji. Di kalangan generasi muda, makin banyak yang berpikir menjawab "terima kasih" dengan jujur membuat percakapan berlanjut lebih nyaman.\n Meski begitu, tak perlu kehilangan makna asli kerendahan hati, yaitu "menghormati lawan bicara". Yang penting mungkin memilih jawaban yang menyampaikan hormat sesuai situasi.',
   [('謙遜の 習慣が 見直されて いる 理由と して 述べられて いるのは どれか。', '褒めた 相手に かえって 失礼に なる 場合が ある から', ['日本人が 褒められる ことが 少なく なった から', '謙遜を すると 会話が 終わる から', '若い 世代は 礼儀を 知らない から'], 'Alasan: bisa tidak sopan pada pemuji.', '褒めてくれた相手に失礼になる場合もある'),
    ('若い 世代に ついて、文章は どう 述べて いるか。', '素直に 感謝を 伝える ほうが 会話が 続くと 考える 人が 増えて いる', ['褒められたら 必ず 否定する', '謙遜を 全く 知らない', '褒める 習慣を 持たない'], 'Generasi muda: jawab dengan terima kasih.', '素直に「ありがとうございます」と答える'),
    ('筆者の 考えに 合う ものは どれか。', '状況に 合わせて、敬意が 伝わる 返事を 選ぶ ことが 大切だ', ['謙遜は 完全に やめる べきだ', '褒められたら いつも 否定する べきだ', '謙遜の 意味は もう 失われた'], 'Pendapat di paragraf akhir.', '状況に応じて、相手に対する敬意が伝わる返事を選ぶ')]),
 C('私の町には、百年以上続く小さな和菓子屋がある。ある日、店主に「なぜ昔ながらの作り方を変えないのですか」と尋ねたところ、意外な答えが返ってきた。\n　「変えていないわけではありません。砂糖の量も、形も、時代に合わせて少しずつ変えてきました。ただ、お客様が『いつもの味』と感じてくださる部分だけは、決して変えないようにしているのです」。\n　私はこの言葉を聞いて、「伝統を守る」ということの意味を考え直した。伝統とは、昔のものをそのまま残すことではなく、変わり続ける中でも、大切な核を守り抜くことなのかもしれない。',
   'Di kota saya ada toko kue Jepang kecil yang berusia lebih dari seratus tahun. Suatu hari saat saya bertanya kepada pemiliknya, "Mengapa Anda tak mengubah cara pembuatan tradisional?", datang jawaban tak terduga.\n "Bukan berarti tidak berubah. Kadar gula dan bentuknya sedikit demi sedikit kami ubah sesuai zaman. Hanya bagian yang membuat pelanggan merasa \'rasa yang biasa\' tak pernah kami ubah."\n Mendengar itu, saya memikirkan ulang arti "menjaga tradisi". Mungkin tradisi bukan melestarikan hal lama apa adanya, melainkan mempertahankan inti penting di tengah perubahan terus-menerus.',
   [('店主の 答えの 内容と して 正しい ものは どれか。', '時代に 合わせて 変えた 部分も あるが、「いつもの 味」は 守って いる', ['百年間 何も 変えて いない', '客の 好みに 関係なく 作り方を 守って いる', '形だけを 昔の まま に して いる'], 'Pemilik: ada perubahan, inti tetap.', '「いつもの味」と感じてくださる部分だけは、決して変えない'),
    ('筆者が 店主の 言葉を 聞いて 考え直した ことは 何か。', '「伝統を 守る」と いう ことの 意味', ['和菓子の 作り方', '店の 経営の 方法', '砂糖の 値段'], 'Penulis memikirkan ulang arti menjaga tradisi.', '「伝統を守る」ということの意味を考え直した'),
    ('筆者は 伝統を どう とらえて いるか。', '変わる 中でも 大切な 核を 守る こと', ['昔の ものを そのまま 残す こと', '時代に 関係なく 変えない こと', '新しい ものを すべて 取り入れる こと'], 'Definisi tradisi menurut penulis.', '変わり続ける中でも、大切な核を守り抜くこと')]),
 C('近年、「シェアハウス」で暮らす若者が増えている。キッチンやリビングを他の住人と共有することで、家賃を抑えられるうえ、人とのつながりも得られるというのが主な理由だ。\n　一方で、生活習慣の違いからトラブルになることも少なくない。例えば、掃除の分担や、夜の騒音などで、住人同士の不満がたまる場合がある。こうした問題を防ぐため、入居前にルールを話し合い、定期的に集まって意見を交換しているシェアハウスもある。\n　他人と暮らすには、それなりの努力が必要だ。しかし、その努力を通して、人の立場を考える力が養われる点は、大きな魅力だといえるだろう。',
   'Belakangan anak muda yang tinggal di "share house" bertambah. Alasan utamanya adalah dengan berbagi dapur dan ruang tamu bersama penghuni lain, sewa bisa ditekan dan juga memperoleh hubungan dengan orang lain.\n Di sisi lain, tak sedikit yang bermasalah karena perbedaan kebiasaan hidup. Misalnya pembagian bersih-bersih atau kebisingan malam bisa menumpuk ketidakpuasan antarpenghuni. Untuk mencegahnya, ada share house yang membahas aturan sebelum masuk dan rutin berkumpul bertukar pendapat.\n Hidup dengan orang lain butuh usaha. Namun lewat usaha itu terlatih kemampuan memikirkan posisi orang lain, dan itu daya tarik besar.',
   [('シェアハウスを 選ぶ 主な 理由と して 述べられて いる ものは どれか。', '家賃を 抑えられ、人との つながりも 得られる こと', ['広い 部屋に 住める こと', '掃除を しなくて よい こと', '騒音が ない こと'], 'Alasan utama: sewa murah dan relasi.', '家賃を抑えられるうえ、人とのつながりも得られる'),
    ('トラブルを 防ぐ ための 工夫と して 挙げられて いる ものは どれか。', '入居前に ルールを 話し合う こと', ['住人を 少なく する こと', '全員で 毎日 食事を する こと', '夜は 外出を 禁止する こと'], 'Pencegahan: bahas aturan sebelum masuk.', '入居前にルールを話し合い'),
    ('筆者が シェアハウスの 魅力と して 挙げて いる ことは 何か。', '人の 立場を 考える 力が 養われる こと', ['家賃が 無料に なる こと', 'トラブルが 全く 起きない こと', '友達が 自然に できる こと'], 'Daya tarik: melatih kemampuan memahami posisi orang.', '人の立場を考える力が養われる点は、大きな魅力')]),
 C('「早く寝なさい」と子どもに言うとき、私たちは睡眠の大切さを知っているつもりでいる。しかし、大人の多くが睡眠不足の状態にあることは、あまり知られていない。\n　ある調査では、日本人の平均睡眠時間は、調査した国の中で最も短い部類に入るという。睡眠が足りないと、集中力や判断力が下がり、仕事のミスも増える。さらに、長期的には健康にも悪い影響が出るとされている。\n　それでも、「忙しいから」と睡眠を削る人は後を絶たない。しかし、睡眠を削って得た時間より、失う効率のほうが大きいのが現実である。まず、自分の睡眠時間を見直してみてはどうだろうか。',
   'Saat menyuruh anak "cepat tidur", kita merasa sudah tahu pentingnya tidur. Namun kenyataan bahwa banyak orang dewasa kekurangan tidur kurang diketahui.\n Menurut sebuah survei, rata-rata waktu tidur orang Jepang termasuk paling singkat di antara negara yang disurvei. Bila kurang tidur, konsentrasi dan daya nilai menurun dan kesalahan kerja bertambah. Dalam jangka panjang juga berdampak buruk pada kesehatan.\n Namun orang yang mengurangi tidur dengan alasan "sibuk" tak ada habisnya. Padahal kenyataannya efisiensi yang hilang lebih besar daripada waktu yang didapat dari memangkas tidur. Mengapa tidak mulai meninjau waktu tidur sendiri?',
   [('筆者が 「あまり 知られて いない」と 述べて いる ことは 何か。', '大人の 多くが 睡眠不足で ある こと', ['子どもの 睡眠時間が 短い こと', '睡眠は 大切では ない こと', '日本人の 睡眠時間が 長い こと'], 'Yang kurang diketahui: orang dewasa kurang tidur.', '大人の多くが睡眠不足の状態にある'),
    ('睡眠不足の 影響と して 述べられて いない ものは どれか。', '食欲が 急に 増える', ['集中力が 下がる', '仕事の ミスが 増える', '長期的に 健康に 悪い'], 'Nafsu makan tidak disebut.', '集中力や判断力が下がり…健康にも悪い影響'),
    ('筆者が 最も 言いたい ことは 何か。', '睡眠を 削るより、睡眠時間を 見直す ほうが 良い', ['忙しい 人は 睡眠を 削る べきだ', '子どもは 早く 寝る 必要は ない', '日本人の 睡眠時間は 十分だ'], 'Ajakan akhir penulis.', '睡眠を削って得た時間より、失う効率のほうが大きい')]),
 C('先日、駅で電車が遅れ、構内は混乱していた。そんな中、一人の駅員が、困っている乗客に丁寧に説明をして回っていた。誰も彼を責めてはいなかったのに、彼は何度も「申し訳ありません」と頭を下げていた。\n　遅れの原因は、駅員のせいではない。それでも、彼は会社の代表として、乗客に誠意を示していたのだと思う。\n　私は、自分が仕事で問題に直面したとき、「自分のせいではない」と言い訳を探してしまうことがある。その駅員の姿を思い出すと、責任の所在よりも、相手の困りごとに向き合う姿勢のほうが大切だと気づかされる。',
   'Beberapa waktu lalu, kereta terlambat di stasiun dan peron kacau. Di tengah itu seorang petugas berkeliling menjelaskan dengan sopan pada penumpang yang kebingungan. Tak seorang pun menyalahkannya, tetapi ia berkali-kali membungkuk meminta maaf.\n Penyebab keterlambatan bukan salah petugas. Namun menurut saya ia menunjukkan ketulusan kepada penumpang sebagai wakil perusahaan.\n Saat saya menghadapi masalah di pekerjaan, kadang saya mencari alasan "bukan salah saya". Mengingat sosok petugas itu, saya disadarkan bahwa sikap menghadapi kesulitan lawan bicara lebih penting daripada soal siapa yang bertanggung jawab.',
   [('駅員は なぜ 何度も 謝って いたと 筆者は 考えて いるか。', '会社の 代表と して 誠意を 示して いた から', ['自分の ミスで 電車が 遅れた から', '乗客に 責められた から', '上司に 命令された から'], 'Penulis: sebagai wakil perusahaan menunjukkan ketulusan.', '会社の代表として、乗客に誠意を示していた'),
    ('筆者は 仕事で 問題に 直面した とき、どう して しまうことが あるか。', '「自分の せいではない」と 言い訳を 探して しまう', ['すぐに 謝って しまう', '問題を 無視して 帰って しまう', '同僚に 責任を 押しつける'], 'Kebiasaan penulis: mencari alasan.', '「自分のせいではない」と言い訳を探してしまう'),
    ('筆者が 駅員の 姿から 気づいた ことは 何か。', '責任の 所在より、相手の 困りごとに 向き合う 姿勢が 大切だと いう こと', ['駅員は 乗客に 謝る べきでは ないと いう こと', '電車の 遅れは 仕方が ないと いう こと', '会社の 責任は 駅員に ある と いう こと'], 'Kesadaran penulis.', '責任の所在よりも、相手の困りごとに向き合う姿勢のほうが大切')]),
 C('日本には、外国人の観光客が増えているが、地方の小さな町では、まだ英語で書かれた案内が少ない。ある町では、地元の高校生がボランティアで、観光地の案内板を英語に翻訳する活動を始めた。\n　生徒たちは、辞書で調べるだけでなく、実際に外国人に読んでもらい、意味が通じるかを確かめている。「直訳すると、意味が伝わらない言葉が多いと分かった」と、ある生徒は話す。\n　この活動は、観光客のためになるだけでなく、生徒たち自身にとっても、自分の町の魅力を見つめ直し、異なる文化との橋渡しをする貴重な機会になっている。',
   'Wisatawan asing di Jepang bertambah, tetapi di kota kecil daerah masih sedikit petunjuk berbahasa Inggris. Di suatu kota, siswa SMA setempat memulai kegiatan sukarela menerjemahkan papan petunjuk objek wisata ke bahasa Inggris.\n Para siswa tak hanya membuka kamus, tetapi meminta orang asing membacanya langsung untuk memeriksa apakah maknanya sampai. "Kami sadar banyak kata yang maknanya tak tersampaikan bila diterjemahkan harfiah," kata seorang siswa.\n Kegiatan ini bukan hanya bermanfaat bagi wisatawan, tetapi juga bagi para siswa sebagai kesempatan berharga meninjau kembali daya tarik kota sendiri dan menjadi jembatan antarbudaya.',
   [('高校生たちは 翻訳の 正確さを どのように 確かめて いるか。', '外国人に 実際に 読んで もらって いる', ['先生に 確認して もらって いる', '辞書だけを 使って いる', 'インターネットで 検索する だけだ'], 'Cara memeriksa: orang asing membaca.', '実際に外国人に読んでもらい'),
    ('ある 生徒が 分かった ことは 何か。', '直訳では 意味が 伝わらない 言葉が 多い', ['英語は 日本語より 簡単だ', '外国人は 日本語が 読める', '辞書は 役に 立たない'], 'Temuan siswa.', '直訳すると、意味が伝わらない言葉が多い'),
    ('この 活動の 意義と して 筆者が 述べて いる ことは 何か。', '生徒が 自分の 町の 魅力を 見つめ直す 機会に なる', ['観光客を 増やす ための 宣伝に なる', '生徒の 英語の 成績が 上がる', '町の 予算が 節約できる'], 'Makna kegiatan.', '自分の町の魅力を見つめ直し')]),
 C('かつて、町の電気屋さんといえば、家電を売るだけでなく、「電球が切れた」「リモコンが動かない」といった小さな困りごとにも気軽に対応してくれる存在だった。\n　ところが、大型の家電量販店が増えてから、町の電気屋さんは次々に姿を消した。価格では大型店に勝てないからだ。\n　しかし、最近、高齢者を中心に、町の電気屋さんを見直す動きがある。「買った後も、何かあればすぐに来てくれる」という安心感が、価格の安さよりも大切だと考える人が増えているのだ。サービスの価値とは、必ずしも値段だけで決まるものではないことを、この例は示している。',
   'Dulu toko listrik di kota bukan hanya menjual alat rumah tangga, tetapi juga mau dengan mudah menolong masalah kecil seperti "lampu putus" atau "remote tak jalan".\n Namun setelah toko elektronik besar bertambah, toko listrik kota satu per satu lenyap karena tak bisa menang dalam harga.\n Namun belakangan, terutama di kalangan lansia, ada gerakan meninjau ulang toko listrik kota. Makin banyak orang menganggap rasa aman "bahkan setelah membeli, mereka datang segera bila ada apa-apa" lebih penting dari murahnya harga. Contoh ini menunjukkan nilai layanan tak selalu ditentukan harga semata.',
   [('町の 電気屋さんが 姿を 消した 理由は 何か。', '価格で 大型店に 勝てなかった から', ['家電が 売れなくなった から', '店主が 高齢に なった から', '修理の 技術が なかった から'], 'Alasan: kalah harga.', '価格では大型店に勝てないからだ'),
    ('最近、町の 電気屋さんが 見直されて いる 理由は 何か。', '買った 後も すぐ 来て くれる 安心感が あるから', ['大型店より 価格が 安い から', '新しい 家電が 多い から', '店が 夜も 開いて いる から'], 'Alasan: rasa aman layanan purna jual.', '買った後も、何かあればすぐに来てくれる安心感'),
    ('筆者が この 例から 言いたい ことは 何か。', 'サービスの 価値は 値段だけでは 決まらない', ['安い 店は 必ず 質が 悪い', '大型店は 無くなる べきだ', '高齢者は 価格を 気に しない'], 'Kalimat penutup.', 'サービスの価値とは、必ずしも値段だけで決まるものではない')]),
 C('学生時代、私は「完璧にできるまで発表しない」と決めていた。失敗して恥をかくのが怖かったからだ。その結果、発表の機会はほとんどなく、成長のチャンスを逃していた。\n　転機は、就職して上司から言われた一言だった。「七割できたら、見せなさい。そこからみんなで直せばいい」。最初は半信半疑だったが、途中で意見をもらうと、一人では気づけなかった問題が見つかり、仕事の質も上がった。\n　今では、完璧を目指すあまり動けなくなるより、早めに見せて改善を重ねるほうが、結果的に良いものができると考えている。',
   'Semasa kuliah saya memutuskan "tak akan presentasi sebelum sempurna", karena takut gagal dan malu. Akibatnya hampir tak ada kesempatan presentasi dan saya kehilangan peluang berkembang.\n Titik baliknya adalah satu kata atasan setelah saya bekerja. "Kalau sudah tujuh puluh persen, tunjukkan. Lalu kita perbaiki bersama." Awalnya setengah percaya, tetapi setelah menerima pendapat di tengah jalan, masalah yang tak terlihat sendiri ditemukan dan kualitas kerja naik.\n Kini saya berpikir daripada tak bisa bergerak karena mengejar sempurna, menunjukkan lebih awal dan terus memperbaiki pada akhirnya menghasilkan yang lebih baik.',
   [('筆者が 学生時代に 発表しなかった 理由は 何か。', '失敗して 恥を かくのが 怖かった から', ['発表の 機会が なかった から', '先生に 禁止された から', '発表が 好きでは なかった から'], 'Alasan: takut malu.', '失敗して恥をかくのが怖かった'),
    ('上司の 言葉を 聞いた 後の 筆者の 経験と して 正しい ものは どれか。', '途中で 意見を もらい、一人では 気づけない 問題が 見つかった', ['七割で 仕事を やめた', '上司に 叱られた', '発表を 避けるように なった'], 'Pengalaman: umpan balik menemukan masalah.', '一人では気づけなかった問題が見つかり'),
    ('筆者の 現在の 考えは どれか。', '早めに 見せて 改善を 重ねる ほうが 良い', ['完璧に なる まで 見せない ほうが 良い', '失敗は 絶対に 避ける べきだ', '上司の 意見は 聞かなくて よい'], 'Pendapat kini.', '早めに見せて改善を重ねるほうが、結果的に良いものができる')]),
 C('新しい言葉は、若者の間で生まれ、やがて社会全体に広がっていく。「やばい」という言葉は、本来は「危険だ」という意味だったが、今では「すばらしい」という意味でも使われる。\n　こうした変化を「言葉の乱れ」と批判する人もいる。しかし、言葉の歴史を振り返ると、今では正しいとされている表現も、かつては「乱れ」と言われたものが少なくない。言葉は生き物であり、使う人々の感覚に合わせて変わっていくのは自然なことなのだ。\n　もちろん、場面に合わない言葉を使えば、相手に誤解を与えることもある。だからこそ、大切なのは、変化を批判することではなく、場面に応じて言葉を選ぶ力を身につけることだろう。',
   'Kata-kata baru lahir di kalangan anak muda dan akhirnya menyebar ke seluruh masyarakat. Kata "yabai" semula berarti "berbahaya", tetapi kini juga dipakai dengan arti "luar biasa".\n Ada yang mengkritik perubahan ini sebagai "kekacauan bahasa". Namun bila menengok sejarah bahasa, tak sedikit ungkapan yang kini dianggap benar dulu juga disebut "kacau". Bahasa adalah makhluk hidup, dan wajar berubah sesuai perasaan pemakainya.\n Tentu bila memakai kata yang tak cocok situasi bisa menimbulkan salah paham. Karena itu yang penting bukan mengkritik perubahan, melainkan memiliki kemampuan memilih kata sesuai situasi.',
   [('「やばい」に ついて、文章は どう 述べて いるか。', '本来は 「危険だ」の 意味だったが、今は 「すばらしい」の 意味でも 使われる', ['昔から 「すばらしい」の 意味だけで 使われて いる', '今は 全く 使われて いない', '若者は 意味を 知らない'], 'Perubahan makna.', '本来は「危険だ」…今では「すばらしい」'),
    ('言葉の 変化を 批判する 人に 対して、筆者は 何を 述べて いるか。', '今は 正しい とされる 表現も かつては 「乱れ」と 言われた', ['言葉は 絶対に 変わらない', '批判する 人は 正しい', '若者の 言葉は すべて 間違いだ'], 'Bantahan penulis: sejarah.', '今では正しいとされている表現も、かつては「乱れ」と言われた'),
    ('筆者が 大切だと 考えて いる ことは 何か。', '場面に 応じて 言葉を 選ぶ 力を 身につける こと', ['新しい 言葉を 使わない こと', '言葉の 変化を 止める こと', '若者の 言葉を 禁止する こと'], 'Kalimat akhir.', '場面に応じて言葉を選ぶ力を身につける')]),
]
